                    }
                }
            } catch (error) {
                logError("迁移旧的 contextMinDepth 设置时出错:", error);
                // Still remove old keys if error occurs during migration logic to prevent re-attempts
                localStorage.removeItem(STORAGE_KEY_CONTEXT_MIN_DEPTH);
