        logDebug("已加载设置: API Config:", customApiConfig, "BreakArmorPrompt starts with:", currentBreakArmorPrompt.substring(0,30), "SummaryPrompt starts with:", currentSummaryPrompt.substring(0,30), "Theme Accent:", currentThemeSettings.accentColor, "Small Chunk:", customSmallChunkSizeSetting, "Large Chunk:", customLargeChunkSizeSetting, "Selected Type:", selectedSummaryType, "Advanced Hide Settings:", currentAdvancedHideSettings);

