    flex-direction: column;
    gap: 25px;
    margin: 15px 5px;
    border: 1px solid #333;
    position: relative;
    overflow: hidden;
  }

  .map_container::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 80px;
    background: linear-gradient(to bottom, rgba(40, 40, 40, 0.2), transparent);
    pointer-events: none;
    border-radius: 16px 16px 0 0;
  }

  .move_block_notice {
    background-color: #2a1515;
    color: #ff8080;
    padding: 12px;
    border-radius: 12px;
    border: 1px solid #662222;
    text-align: center;
    font-weight: bold;
    margin-bottom: 15px;
    box-shadow: inset 2px 2px 5px rgba(0, 0, 0, 0.5),
                inset -2px -2px 5px rgba(80, 40, 40, 0.1);
  }

  .map_title_bar {
    text-align: center;
    margin-bottom: 15px;
    padding-bottom: 10px;
    border-bottom: 1px solid #333;
    grid-column: 1 / -1;
  }

  .map_title_bar h3 {
    color: #aaa;
    font-size: 16px;
    margin: 0;
    text-transform: uppercase;
    letter-spacing: 1px;
  }

  .main_locations_container, .sub_location_container {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
    gap: 15px;
  }

  .main_location, .sub_location {
    padding: 15px;
    background: #252525;
    border-radius: 12px;
    cursor: default;
    transition: all 0.3s ease;
    box-shadow: 6px 6px 12px rgba(0, 0, 0, 0.4),
                -6px -6px 12px rgba(60, 60, 60, 0.1);
    border: 1px solid #333;
    position: relative;
    overflow: hidden;
    height: 100%;
    display: flex;
    flex-direction: column;
  }

  .last_mes .main_location, .last_mes .sub_location {
    cursor: pointer;
  }

  .last_mes .main_location:hover, .last_mes .sub_location:hover {
    background: #2a2a2a;
    transform: translateY(-3px);
    box-shadow: 8px 8px 16px rgba(0, 0, 0, 0.5),
                -8px -8px 16px rgba(60, 60, 60, 0.15);
    z-index: 1;
  }

  .last_mes .main_location:active, .last_mes .sub_location:active {
    transform: translateY(0);
    box-shadow: 4px 4px 8px rgba(0, 0, 0, 0.4),
                -4px -4px 8px rgba(60, 60, 60, 0.1);
    background: #222;
  }

  .main_location.selected, .sub_location.selected {
    background: #2d3436;
    border-color: #00a8ff;
    box-shadow: 0 0 15px rgba(0, 168, 255, 0.3),
                6px 6px 12px rgba(0, 0, 0, 0.4),
                -6px -6px 12px rgba(60, 60, 60, 0.1);
    z-index: 2;
  }

  .main_location.selected::before, .sub_location.selected::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 5px;
    height: 100%;
    background: linear-gradient(to bottom, #00a8ff, #0097e6);
  }

  .location_name {
    font-weight: bold;
    font-size: 15px;
    display: block;
    margin-bottom: 8px;
    color: #fff;
    text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.8);
  }

  .characters_list {
    margin-top: 8px;
    display: flex;
    flex-wrap: wrap;
    gap: 5px;
  }

  .character_name {
    display: inline-block;
    background: linear-gradient(145deg, #252525, #202020);
    padding: 4px 8px;
    margin: 2px;
    border-radius: 4px;
    color: #ddd;
    box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.3);
    font-size: 11px;
    border: 1px solid #333;
  }

  .map_action_area {
    display: flex;
    justify-content: center;
    padding-top: 15px;
    margin-top: 10px;
    border-top: 1px solid #333;
    grid-column: 1 / -1; /* 占据整行 */
  }

  .go_button {
    padding: 12px 25px;
    background: linear-gradient(145deg, #2c2c2c, #242424);
    border: none;
    border-radius: 30px;
    color: #fff;
    font-size: 14px;
    transition: all 0.3s ease;
    cursor: pointer;
    box-shadow: 4px 4px 8px rgba(0, 0, 0, 0.4),
                -4px -4px 8px rgba(60, 60, 60, 0.1);
    position: relative;
    overflow: hidden;
  }

  .go_button::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.1), transparent);
    transition: all 0.5s ease;
  }

  .go_button:not(.disabled):hover {
    background: linear-gradient(145deg, #333, #292929);
    transform: translateY(-2px);
    box-shadow: 6px 6px 12px rgba(0, 0, 0, 0.5),
                -6px -6px 12px rgba(60, 60, 60, 0.15);
  }

  .go_button:not(.disabled):hover::before {
    left: 100%;
  }

  .go_button:not(.disabled):active {
    transform: translateY(0);
    box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.4),
                -2px -2px 5px rgba(60, 60, 60, 0.1);
    background: linear-gradient(145deg, #222, #1e1e1e);
  }

  .go_button.disabled {
    opacity: 0.5;
    cursor: not-allowed;
    background: linear-gradient(145deg, #222, #1e1e1e);
  }

  /* 响应式布局 */
  @media (max-width: 600px) {
    .main_locations_container, .sub_location_container {
      grid-template-columns: repeat(2, 1fr);
    }
  }

  @media (min-width: 601px) and (max-width: 900px) {
    .main_locations_container, .sub_location_container {
      grid-template-columns: repeat(3, 1fr);
    }
  }

  @media (min-width: 901px) {
    .main_locations_container, .sub_location_container {
      grid-template-columns: repeat(4, 1fr);
    }
  }

  /* 自定义滚动条 */
  .map_container::-webkit-scrollbar {
    width: 8px;
  }

  .map_container::-webkit-scrollbar-track {
    background: #1a1a1a;
    border-radius: 4px;
  }

  .map_container::-webkit-scrollbar-thumb {
    background: #333;
    border-radius: 4px;
    border: 2px solid #1a1a1a;
  }

  .map_container::-webkit-scrollbar-thumb:hover {
    background: #444;
  }
</style>
