  async function deleteLorebookEntry_EH(uid) { // Renamed function (though logic is general)
    if (!coreApisAreReady_EH || !TavernHelper_API_EH) { showToastr_EH('error', '核心API未就绪，无法删除条目。'); return false; }
    try {
      const primaryLorebookName = await TavernHelper_API_EH.getCurrentCharPrimaryLorebook();
      if (!primaryLorebookName) { showToastr_EH('warning', '当前角色未设置主世界书。'); return false; }
      const uidStr = String(uid); logDebug_EH(`Attempting to delete lorebook entry with UID: ${uidStr} using Get-Filter-Set method.`);
      const allEntries = await TavernHelper_API_EH.getLorebookEntries(primaryLorebookName);
      if (!allEntries.some(entry => String(entry.uid) === uidStr)) { logWarn_EH(`Entry with UID ${uidStr} not found. Might be already deleted.`); return true; }
      const entriesToKeep = allEntries.filter(entry => String(entry.uid) !== uidStr);
      await TavernHelper_API_EH.replaceLorebookEntries(primaryLorebookName, entriesToKeep);
      logDebug_EH(`EH: "replaceLorebookEntries" call for UID ${uidStr} completed. Verifying...`);
      await new Promise(resolve => setTimeout(resolve, 300));
      const entriesAfterDelete = await TavernHelper_API_EH.getLorebookEntries(primaryLorebookName);
      const entryStillExists = entriesAfterDelete.some(entry => String(entry.uid) === uidStr);
      if (entryStillExists) { logError_EH(`DELETION VERIFICATION FAILED: UID ${uidStr} still exists.`); showToastr_EH('error', `删除验证失败：条目 ${uidStr} 依然存在。`); return false; }
      else { logDebug_EH(`DELETION VERIFICATION SUCCESS: UID ${uidStr} removed.`); return true; }
    } catch (error) { logError_EH(`Error during Get-Filter-Set deletion for UID ${uid}:`, error); showToastr_EH('error', `删除世界书条目时发生错误: ${error.message}`); return false; }
  }

  async function loadEmailsFromLorebook_EH() { // Renamed function
    logDebug_EH('EH: Loading emails from lorebook...');
    if (!coreApisAreReady_EH || !TavernHelper_API_EH) { showToastr_EH('error', '核心API未就绪，无法加载邮件。'); return []; }
    try {
      const primaryLorebookName = await TavernHelper_API_EH.getCurrentCharPrimaryLorebook();
      if (!primaryLorebookName) { showToastr_EH('warning', '当前角色未设置主世界书。'); return []; }
      const entries = await TavernHelper_API_EH.getLorebookEntries(primaryLorebookName);
      if (!Array.isArray(entries) || entries.length === 0) { showToastr_EH('info', '主世界书为空，没有邮件可加载。'); return []; }
      const loadedEmails = [];
      const emailContentEntryPrefix = `☆EMAIL☆${currentChatFileIdentifier_EH}☆`; // Changed prefix

      for (const entry of entries) {
        if (entry.comment && entry.comment.startsWith(emailContentEntryPrefix)) {
          try {
            const emailDataFromContent = JSON.parse(entry.content);
            const fullEmailObject = {
              ...entry, ...emailDataFromContent, id: String(entry.uid),
            };
            delete fullEmailObject.content; // No longer needed at top level
            if (!fullEmailObject.timestamp) fullEmailObject.timestamp = new Date(0).getTime();
            if (!fullEmailObject.lastUpdatedTimestamp) fullEmailObject.lastUpdatedTimestamp = fullEmailObject.timestamp;
            loadedEmails.push(fullEmailObject);
          } catch (e) {
            logError_EH(`Failed to parse email JSON (UID: ${entry.uid}, Comment: ${entry.comment}). Error:`, e);
          }
        }
      }
      logDebug_EH(`EH: Loaded ${loadedEmails.length} emails from lorebook.`);
      return loadedEmails;
    } catch (error) { logError_EH('EH: Error loading emails from lorebook:', error); showToastr_EH('error', `从世界书加载邮件失败: ${error.message}`); return []; }
  }

