  async function callConfiguredApi_EH(messages, jsonMode = false) { // Renamed function
    if (!customApiConfig_EH.url || !customApiConfig_EH.model) throw new Error('API URL/Model未配置。');
    let fullApiUrl = customApiConfig_EH.url; if (!fullApiUrl.endsWith('/')) fullApiUrl += '/';
    if (fullApiUrl.includes('generativelanguage.googleapis.com')) { if (!fullApiUrl.endsWith('chat/completions')) fullApiUrl += 'chat/completions'; }
    else if (fullApiUrl.endsWith('/v1/')) fullApiUrl += 'chat/completions'; else if (!fullApiUrl.includes('/chat/completions')) fullApiUrl += 'v1/chat/completions';
    const headers = { 'Content-Type': 'application/json' }; if (customApiConfig_EH.apiKey) headers['Authorization'] = `Bearer ${customApiConfig_EH.apiKey}`;
    const bodyPayload = { model: customApiConfig_EH.model, messages: messages, stream: false, };
    if (jsonMode) bodyPayload.response_format = { type: 'json_object' };
    const body = JSON.stringify(bodyPayload);
    logDebug_EH('EH Calling API:', fullApiUrl, 'Model:', customApiConfig_EH.model, 'JSON Mode:', jsonMode); logDebug_EH('--- API Request Payload ---'); logDebug_EH(JSON.stringify(messages, null, 2)); logDebug_EH('--------------------------');
    let response; try { response = await fetch(fullApiUrl, { method: 'POST', headers: headers, body: body }); } catch (error) { logError_EH('Network error during fetch:', error); throw new Error(`网络请求失败: ${error.message}。请检查网络连接、API地址是否正确，或是否存在CORS跨域问题。`); }
    if (!response.ok) { const errTxt = await response.text(); logError_EH(`API request failed with status ${response.status}:`, errTxt); throw new Error(`API请求失败: ${response.status} ${response.statusText}。服务器返回: ${errTxt}`); }
    const data = await response.json(); logDebug_EH('--- API Raw Response Data ---'); logDebug_EH(JSON.stringify(data, null, 2)); logDebug_EH('----------------------------');
    if (data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content) { const content = data.choices[0].message.content.trim(); logDebug_EH('--- Extracted AI Content ---'); logDebug_EH(content); logDebug_EH('---------------------------'); return content; }
    throw new Error('API响应格式不正确或内容为空。');
  }

  async function handleAIGenerateEmails_EH(allEmails, resultArea, floorRange = null) { // Renamed function
    logDebug_EH('--- Starting AI Email Generation ---');
    if (!customApiConfig_EH.url || !customApiConfig_EH.model) { showToastr_EH('warning', '请先在设置中配置API信息。'); if (resultArea) resultArea.textContent = '错误：API未配置。'; return false; }
    const aiGenerateEmailsBtn = $mainPanelInstance_EH ? $mainPanelInstance_EH.find('#aiGenerateEmailsBtn')[0] : null; // Renamed ID
    let spinner; if (aiGenerateEmailsBtn) { aiGenerateEmailsBtn.disabled = true; spinner = document.createElement('span'); spinner.className = 'loading-spinner'; aiGenerateEmailsBtn.appendChild(spinner); }
    if (resultArea) resultArea.textContent = 'AI正在构思新邮件，请稍候...';
    try {
      logDebug_EH('Step 1: Preparing core context...'); if (resultArea) resultArea.textContent = '正在收录世界观和最新聊天记录...';
      await loadAllChatMessages_EH();
      let messagesForContext; let contextDepth = autoGenerateThreshold_EH;
      if ($mainPanelInstance_EH) { const $contextDepthInput = $mainPanelInstance_EH.find('#eh-context-depth-input'); if ($contextDepthInput.length > 0) { const val = parseInt($contextDepthInput.val(), 10); if (!isNaN(val) && val >= 1) contextDepth = val; } }
      messagesForContext = allChatMessages_EH.slice(-contextDepth); logDebug_EH(`Using contextDepth for AI context: ${contextDepth}. Sliced ${messagesForContext.length} messages.`);
      const chatHistorySummary = messagesForContext.map(msg => `${msg.name}: ${msg.message}`).join('\n');
      const coreContext = `--- 核心参考资料 ---\n[最近的聊天记录]\n${chatHistorySummary || '(无聊天记录)'}\n--- 核心参考资料结束 ---`;

      logDebug_EH('Step 2: Building the final AI prompt...');
      let focusTopic = ''; if ($mainPanelInstance_EH) { const topicInput = $mainPanelInstance_EH.find('#newEmailTopicInput')[0]; if (topicInput) focusTopic = topicInput.value.trim(); } // Renamed ID
      const topicText = focusTopic ? `\n\n--- 用户指定的焦点主题 ---\n"${focusTopic}"\n--- 焦点主题结束 ---` : '';
      const userPrompt = `${coreContext}${topicText}`;
      let finalSystemPrompt = SENDER_PERSONA_PROMPTS_EH[currentSelectedPersona_EH] || DEFAULT_SENDER_PERSONA_PROMPT_EH;
      const messages = [{ role: 'system', content: `${currentBreakArmorPrompt_EH}\n\n${finalSystemPrompt}` }, { role: 'user', content: userPrompt }, ];
      logDebug_EH(`Prompt construction complete. System prompt length: ${messages[0].content.length}, User prompt length: ${messages[1].content.length}`);
      if (resultArea) resultArea.textContent = '已向AI发送请求，正在等待返回...';
      logDebug_EH('Step 3: Calling the API...');
      const aiResponseJson = await callConfiguredApi_EH(messages, true); logDebug_EH('AI Raw Response JSON:', aiResponseJson);
      if (!aiResponseJson || aiResponseJson.trim() === '') throw new Error('AI未能生成有效的JSON内容。');
      if (resultArea) resultArea.textContent = '已收到AI响应，正在解析和保存数据...';
      logDebug_EH('Step 4: Parsing AI response and saving data...');
      let parsedResponse;
      try {
        let cleanedJsonString = aiResponseJson.replace(/^```json\s*|```$/g, '').trim();
        const startIndex = cleanedJsonString.indexOf('{'); const endIndex = cleanedJsonString.lastIndexOf('}');
        if (startIndex !== -1 && endIndex !== -1 && endIndex > startIndex) cleanedJsonString = cleanedJsonString.substring(startIndex, endIndex + 1);
        else { logError_EH('AI response does not contain a valid JSON object structure.', aiResponseJson.substring(0, 100)); throw new Error(`AI返回的内容中未找到有效的JSON对象。`); }
        cleanedJsonString = cleanedJsonString.replace(/"[^"]+:\s*"(sender|subject|body)"/g, '"$1"'); // Adapted keys
        parsedResponse = JSON.parse(cleanedJsonString);
      } catch (e) { logError_EH('Failed to parse JSON from AI response.', aiResponseJson.substring(0, 100)); throw new Error(`AI返回的不是有效的JSON格式。解析错误: ${e.message}.`); }

      let { new_emails } = parsedResponse;
      let savedCount = 0;
      if (new_emails && Array.isArray(new_emails)) {
        for (const [index, email] of new_emails.entries()) {
          if (email.sender && email.subject && email.body) {
            const now = new Date().getTime();
            const newEmailObject = {
              id: null, sender: email.sender, subject: `[新邮件] ${email.subject}`, body: email.body,
              timestamp: now, lastUpdatedTimestamp: now, basedOnFloors: floorRange,
            };
            const savedEmail = await saveEmailLorebookEntry_EH(newEmailObject, index); // Renamed function
            if (savedEmail) { allEmails.push(savedEmail); savedCount++; }
          }
        }
      }
      const summaryMessage = `邮件生成完成！新增 ${savedCount} 封邮件。`;
      logDebug_EH(`--- AI Email Generation Complete ---`); logDebug_EH(summaryMessage);
      if (resultArea) resultArea.textContent = `${summaryMessage} 正在刷新收件箱...`;
      showToastr_EH('success', summaryMessage);
    } catch (error) { logError_EH('Error during AI email generation:', error); if (resultArea) resultArea.textContent = `AI邮件生成失败: ${error.message}`; showToastr_EH('error', `AI邮件生成失败: ${error.message}`); return false; }
    finally { if (aiGenerateEmailsBtn) { aiGenerateEmailsBtn.disabled = false; if (aiGenerateEmailsBtn.querySelector('.loading-spinner')) aiGenerateEmailsBtn.removeChild(aiGenerateEmailsBtn.querySelector('.loading-spinner')); } }
    return true;
  }

  async function saveEmailLorebookEntry_EH(emailObject, index = null) { // Renamed function
    if (!coreApisAreReady_EH || !TavernHelper_API_EH) { logError_EH('saveEmailLorebookEntry_EH: Core APIs not ready.'); showToastr_EH('error', `保存邮件 "${emailObject.subject}" 失败：核心API未就绪。`); return null; }
    const chatIdentifierForEntry = currentChatFileIdentifier_EH || '未知聊天';
    if (chatIdentifierForEntry === '未知聊天') { logError_EH('Cannot save email, chat identifier is unknown.'); showToastr_EH('error', '保存邮件失败：无法识别当前聊天。'); return null; }
    try {
      const primaryLorebookName = await TavernHelper_API_EH.getCurrentCharPrimaryLorebook();
      if (!primaryLorebookName) { logError_EH('No primary lorebook set.'); showToastr_EH('error', '保存失败：当前角色未设置主世界书。'); return null; }
      const dataToSave = { ...emailObject }; delete dataToSave.id;
      const newEntryContent = JSON.stringify(dataToSave, null, 2);
      const safeEmailSubjectForKeys = (emailObject.subject || 'untitled').replace(/[^a-zA-Z0-9\u4e00-\u9fa5_-]/g, '_').substring(0, 50);
      if (emailObject.id) {
        logDebug_EH(`EH Email: Updating email. UID: "${emailObject.id}"`);
        const allEntries = await TavernHelper_API_EH.getLorebookEntries(primaryLorebookName);
        const originalEntry = allEntries.find(entry => String(entry.uid) === String(emailObject.id));
        if (!originalEntry) throw new Error(`无法找到要更新的原始世界书条目，UID: ${emailObject.id}`);
        const updatedEntryData = { ...originalEntry, content: newEntryContent, };
        await TavernHelper_API_EH.setLorebookEntries(primaryLorebookName, [updatedEntryData]);
        await new Promise(resolve => setTimeout(resolve, 300));
        const entriesAfterUpdate = await TavernHelper_API_EH.getLorebookEntries(primaryLorebookName);
        const updatedEntryFromServer = entriesAfterUpdate.find(entry => String(entry.uid) === String(emailObject.id));
        let isVerified = false; if (updatedEntryFromServer) { try { const parsedSavedContent = JSON.parse(updatedEntryFromServer.content); const reStringifiedContent = JSON.stringify(parsedSavedContent, null, 2); if (reStringifiedContent === newEntryContent) isVerified = true; } catch (e) { /* ignore */ } }
        if (!isVerified) { logError_EH(`UPDATE VERIFICATION FAILED for UID ${emailObject.id}.`); logDebug_EH('Expected content:', newEntryContent); logDebug_EH('Actual content:', updatedEntryFromServer ? updatedEntryFromServer.content : 'NOT FOUND'); throw new Error(`更新世界书条目 UID ${emailObject.id} 后验证失败。`); }
        logDebug_EH(`UPDATE VERIFICATION SUCCESS for UID ${emailObject.id}.`);
        return emailObject;
      } else {
        let newEntryComment;
        if (emailObject.basedOnFloors) { newEntryComment = `☆EMAIL☆${chatIdentifierForEntry}☆${emailObject.basedOnFloors.start + 1}-${emailObject.basedOnFloors.end + 1}`; if (index !== null) newEntryComment += `☆${index}`; } // Changed prefix
        else { await loadAllChatMessages_EH(); const currentMessageCount = allChatMessages_EH.length > 0 ? allChatMessages_EH.length : 1; newEntryComment = `☆EMAIL☆${chatIdentifierForEntry}☆${currentMessageCount}-${currentMessageCount}`; emailObject.basedOnFloors = { start: currentMessageCount - 1, end: currentMessageCount - 1 }; } // Changed prefix
        logDebug_EH(`EH Email: Creating new email. Entry comment: "${newEntryComment}"`);
        const newEntryData = { comment: newEntryComment, content: newEntryContent, keys: [`EH_Email`, chatIdentifierForEntry, safeEmailSubjectForKeys], enabled: true, type: 'selective', order: 1000, position: 'after_character_definition', probability: 100, logic: 'and_any', }; // Changed key prefix
        await TavernHelper_API_EH.createLorebookEntries(primaryLorebookName, [newEntryData]);
        let foundEntry = null; for (let i = 0; i < 3; i++) { await new Promise(resolve => setTimeout(resolve, 500)); const allEntries = await TavernHelper_API_EH.getLorebookEntries(primaryLorebookName); foundEntry = allEntries.find(entry => entry.comment === newEntryComment); if (foundEntry) break; }
        if (foundEntry && foundEntry.uid) { emailObject.id = String(foundEntry.uid); return emailObject; }
        else throw new Error('创建世界书条目后未能获取UID。');
      }
    } catch (error) { logError_EH(`Error saving email content for "${emailObject.subject}":`, error); showToastr_EH('error', `保存邮件 "${emailObject.subject}" 失败: ${error.message}`); return null; }
  }

  async function handleManualEmailGeneration_EH() { // Renamed function
    if (isAutoGeneratingEmails_EH) { showToastr_EH('info', '已有邮件生成任务在后台进行中。'); return; }
    if (!customApiConfig_EH.url || !customApiConfig_EH.model) { showToastr_EH('warning', '请先配置API信息。'); if ($settingsPopupInstance_EH && $apiConfigAreaDiv_EH && $apiConfigAreaDiv_EH.is(':hidden')) if ($apiConfigSectionToggle_EH) $apiConfigSectionToggle_EH.trigger('click'); if ($customApiUrlInput_EH) $customApiUrlInput_EH.focus(); return; }
