      const allEmails = await loadEmailsFromLorebook_EH(); // Renamed function
      if (resultArea) resultArea.textContent = '手动邮件生成任务已启动...';
      const success = await handleAIGenerateEmails_EH(allEmails, resultArea); // Renamed function
      if (success) { showToastr_EH('success', '手动生成新邮件成功！'); if (resultArea) resultArea.textContent = '手动生成成功！'; if ($mainPanelInstance_EH) { const initialLoadEmails = $mainPanelInstance_EH.data('initialLoadEmails'); if (typeof initialLoadEmails === 'function') await initialLoadEmails(); } } // Renamed function reference
      else { showToastr_EH('error', '手动生成新邮件失败。'); if (resultArea) resultArea.textContent = '手动生成失败，请查看控制台日志。'; }
    } catch (error) { logError_EH('Manual email generation failed:', error); showToastr_EH('error', `手动生成邮件出错: ${error.message}`); }
    finally { isAutoGeneratingEmails_EH = false; if ($manualEmailGenerateButton_EH) $manualEmailGenerateButton_EH.prop('disabled', false).text('立即生成新邮件'); } // Renamed variable
  }

  async function manageEmailLorebookEntries_EH() { // Renamed function
    if (!coreApisAreReady_EH || !TavernHelper_API_EH || !SillyTavern_API_EH) { logWarn_EH('manageEmailLorebookEntries_EH: Core APIs not ready.'); return; }
    logDebug_EH('EH: Managing email lorebook entries...');
    try {
      const primaryLorebookName = await TavernHelper_API_EH.getCurrentCharPrimaryLorebook();
      if (!primaryLorebookName) { logDebug_EH('EH: No primary lorebook. Skipping entry management.'); return; }
      let masterToggleEnabled = true; try { const toggleStates = JSON.parse(localStorage.getItem(STORAGE_KEY_LOREBOOK_TOGGLE_STATE_EH) || '{}'); if (toggleStates[primaryLorebookName] === false) masterToggleEnabled = false; } catch (e) { logError_EH('Failed to read lorebook toggle states', e); }
      let entries = await TavernHelper_API_EH.getLorebookEntries(primaryLorebookName); if (!Array.isArray(entries) || entries.length === 0) { logDebug_EH('EH: Primary lorebook empty.'); return; }
      const entryPrefixGeneral = `☆EMAIL☆`; // Changed prefix
      const currentChatIdForEntry = currentChatFileIdentifier_EH || '未知聊天';
      const entryPrefixCurrentActiveChat = currentChatIdForEntry !== '未知聊天' ? `${entryPrefixGeneral}${currentChatIdForEntry}☆` : null;
      logDebug_EH(`EH: Current chat for lorebook management: ${currentChatIdForEntry}`);
      const entriesToUpdate = [];
      for (const entry of entries) {
        if (entry.comment && entry.comment.startsWith(entryPrefixGeneral)) {
          let shouldBeEnabled = !masterToggleEnabled ? false : (entryPrefixCurrentActiveChat && entry.comment.startsWith(entryPrefixCurrentActiveChat));
          if ((entry.enabled !== undefined && entry.enabled !== shouldBeEnabled) || entry.enabled === undefined) { logDebug_EH(`EH: Entry "${entry.comment}" (UID: ${entry.uid}) current enabled: ${entry.enabled}, target: ${shouldBeEnabled}`); entriesToUpdate.push({ uid: entry.uid, enabled: shouldBeEnabled }); }
        }
      }
      if (entriesToUpdate.length > 0) { logDebug_EH(`EH: Found ${entriesToUpdate.length} entries to update for chat "${currentChatIdForEntry}".`); await TavernHelper_API_EH.setLorebookEntries(primaryLorebookName, entriesToUpdate); logDebug_EH(`EH: Lorebook entries updated for chat "${currentChatIdForEntry}".`); }
      else logDebug_EH('EH: No lorebook entries needed update.');
    } catch (error) { logError_EH('EH: Error managing email lorebook entries:', error); showToastr_EH('error', `管理邮件世界书条目时出错: ${error.message}`); }
  }
