    function shortenEntityId(entityId) {
        if (typeof entityId !== 'string') return '未知';
        if (entityId.startsWith('char-')) return entityId.substring(0, 12) + '...'; // Example: char-abcdefgh...
        if (entityId.startsWith('group-')) return entityId.substring(0, 13) + '...';// Example: group-abcdef...
        return entityId; // For 'default' or other short IDs
    }

    function updateAdvancedHideUIDisplay() {
        // Removed $hideLastNInput and $hideModeToggleButton as they are being removed from UI.
        if (!$popupInstance || !$hideCurrentValueDisplay) {
            logDebug("updateAdvancedHideUIDisplay: UI elements not ready ($hideCurrentValueDisplay missing).");
            return;
        }

        // const settings = currentAdvancedHideSettings; // Settings object might be less relevant now.
        // const entityId = getCurrentEntityId(); // Entity ID might be less relevant if mode toggle is gone.

        // effectiveConfig.hideLastN is now N+10, where N is the chunk size.
        // We need to call getEffectiveChunkSize again here to get N.
        const autoChunkSizeForDisplay = getEffectiveChunkSize("system_auto_hide_display"); // This is N
        let displayValue;
        let baseChunkValueText = autoChunkSizeForDisplay; // Text representation of N

        if (autoChunkSizeForDisplay <= 0) {
            // If chunk size N is 0 or less, applyActualMessageVisibility keeps 0 (show all).
            displayValue = "全部"; // Display "全部" when N <= 0
            baseChunkValueText = "0 (无效)"; // Indicate the base chunk size was invalid
        } else {
            // displayValue = autoChunkSizeForDisplay + 10; // Calculate N + 10 for display // BUG: Hardcoded +10
            displayValue = autoChunkSizeForDisplay + currentVisibilityOffset; // FIX: Use the actual offset X
        }

        // The "source" is now always "自动 (总结类型)".
        const currentSummaryTypeName = selectedSummaryType === 'small' ? '小总结' : '大总结';
        // Read the *current* offset value again for logging, just to be sure.
        const currentOffsetForLog = currentVisibilityOffset;
        const autoAppliedSuffix = ` (基于 "${currentSummaryTypeName}" 层数 ${baseChunkValueText} + ${currentOffsetForLog})`;
        const finalText = `当前生效: 保留 ${displayValue} 条${autoAppliedSuffix}`;

        logDebug(`[UpdateHideUI] Calculated: N=${autoChunkSizeForDisplay}, X=${currentOffsetForLog}, DisplayValue=${displayValue}, Type=${currentSummaryTypeName}. Final Text: "${finalText}"`);
        $hideCurrentValueDisplay.text(finalText);
        logDebug(`[UpdateHideUI] UI element text updated.`);
    }

